body {
    font-family: Arial, sans-serif;
    background: linear-gradient(180deg, #e8f5e9 0%, #f7fbf7 100%);
    margin: 0;
    min-height: 100vh;
    color: #1f2d1f;
}

.container {
    width: min(900px, 92%);
    margin: 40px auto;
    padding: 28px;
    background: #ffffff;
    border: 1px solid #c8e6c9;
    border-radius: 18px;
    box-shadow: 0 12px 30px rgba(27, 94, 32, 0.12);
}

h2 {
    margin-bottom: 24px;
    color: #1b5e20;
    font-weight: 700;
    letter-spacing: 0.2px;
}

.form-group {
    margin-bottom: 16px;
}

.form-label,
label {
    font-weight: 600;
    color: #245b2b;
    margin-bottom: 6px;
}

input[type="text"],
input[type="date"],
select,
.form-control,
.form-select {
    width: 100%;
    padding: 11px 14px;
    margin-top: 5px;
    border: 1px solid #a5d6a7;
    border-radius: 10px;
    background-color: #fafffa;
    transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

input[type="text"]:focus,
input[type="date"]:focus,
select:focus,
.form-control:focus,
.form-select:focus {
    border-color: #1b5e20;
    outline: none;
    box-shadow: 0 0 0 0.2rem rgba(27, 94, 32, 0.15);
}

.form-check {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 6px;
}

.form-check-input {
    width: 20px;
    height: 20px;
    margin: 0;
    cursor: pointer;
    accent-color: #1b5e20;
}

.form-check-label {
    margin: 0;
    cursor: pointer;
}

button,
.btn-success {
    padding: 10px 20px;
    margin: 8px 10px 0 0;
    border: 1px solid #1b5e20;
    border-radius: 10px;
    background-color: #0f5132;
    color: white;
    cursor: pointer;
    transition: background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 6px 16px rgba(15, 81, 50, 0.2);
}

button:hover,
.btn-success:hover {
    background-color: #1b5e20;
    transform: translateY(-1px);
}

button:active,
.btn-success:active {
    transform: translateY(0);
    box-shadow: 0 3px 8px rgba(15, 81, 50, 0.18);
}

@media (max-width: 576px) {
    .container {
        width: 94%;
        margin: 16px auto;
        padding: 18px;
        border-radius: 14px;
    }

    button,
    .btn-success {
        width: 100%;
        margin-right: 0;
    }
}
